import{_ as t,o,c as d,a2 as r}from"./chunks/framework.Cxtv3Pj-.js";const g=JSON.parse('{"title":"Configuration Properties","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config-properties.md","filePath":"reference/config-properties.md","lastUpdated":1785719861000}'),a={name:"reference/config-properties.md"};function i(n,e,s,l,c,h){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration-properties" tabindex="-1">Configuration Properties <a class="header-anchor" href="#configuration-properties" aria-label="Permalink to &quot;Configuration Properties&quot;">​</a></h1><p>Following is the list of configuration properties for generating your project from the TrueLicense Maven Archetype in alphabetic order. Please check the <a href="/guide/example-configurations">Example Configurations</a> page to see how to apply these properties.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Property names and values are case-sensitive.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you want to change the value of these properties, then it’s generally necessary to <strong>regenerate the project</strong> from the TrueLicense Maven Archetype.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Even if all their property values are equal, the license keys of any two generated projects will not be compatible unless both projects <strong>also share the following key store files</strong> (see below for default values):</p><ul><li><code>keygen/src/main/resources/${privateKeyStoreFile}</code></li><li><code>keymgr/src/main/resources/${ftpKeyStoreFile}</code></li><li><code>keymgr/src/main/resources/${publicKeyStoreFile}</code></li></ul></div><h2 id="required-properties" tabindex="-1">Required Properties <a class="header-anchor" href="#required-properties" aria-label="Permalink to &quot;Required Properties&quot;">​</a></h2><h3 id="artifactid" tabindex="-1"><code>artifactId</code> <a class="header-anchor" href="#artifactid" aria-label="Permalink to &quot;`artifactId`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The Maven artifact ID of the root <a href="https://maven.apache.org/guides/introduction/introduction-to-the-pom.html" target="_blank" rel="noreferrer">POM</a> for the generated project. This could match the name of your software product, e.g. <code>product</code>, or be generic, e.g. <code>license</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>A Maven artifact ID must not contain spaces and should consist of only lower-case characters - see <a href="https://maven.apache.org/pom.html#Maven_Coordinates" target="_blank" rel="noreferrer">Maven Coordinates</a>.</p></dd></dl><h3 id="company" tabindex="-1"><code>company</code> <a class="header-anchor" href="#company" aria-label="Permalink to &quot;`company`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The display name of your company, e.g. <code>Company Inc.</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd></dl><h3 id="groupid" tabindex="-1"><code>groupId</code> <a class="header-anchor" href="#groupid" aria-label="Permalink to &quot;`groupId`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The Maven group ID for the generated project. This could be the reversed domain name for your company plus the name of the software product.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>A Maven group ID must not contain spaces and should consist of only lower-case characters - see <a href="https://maven.apache.org/pom.html#Maven_Coordinates" target="_blank" rel="noreferrer">Maven Coordinates</a>.</p></dd></dl><h3 id="password" tabindex="-1"><code>password</code> <a class="header-anchor" href="#password" aria-label="Permalink to &quot;`password`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The common password for accessing keystores and encrypting license keys.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>A string of at least eight characters which must contain letters and digits. You should consider this to be the bare minimum. Choosing a longer password with additional punctuation characters significantly improves the security level of your licensing schema.</p></dd></dl><h3 id="subject" tabindex="-1"><code>subject</code> <a class="header-anchor" href="#subject" aria-label="Permalink to &quot;`subject`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The license management subject. The value of this property gets stored in the generated license keys and is used for validation. A <code>global.namespace.truelicense.api.LicenseValidationException</code> gets thrown if the validation fails. It&#39;s best practice including the name of your software product, and a version number range for which the license keys are valid, e.g. <code>Product 1</code> or <code>Product 1.X</code>. The license validation step compares the entire string, so the version number format doesn&#39;t matter. If you want to obsolete existing license keys in a future release then all you need to do is to change the value of this property, e.g. to <code>Product 2</code> or <code>Product 2.X</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd></dl><h3 id="version" tabindex="-1"><code>version</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;`version`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The Maven version for the generated project. This should match the version of your software product.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd></dl><h2 id="optional-properties" tabindex="-1">Optional Properties <a class="header-anchor" href="#optional-properties" aria-label="Permalink to &quot;Optional Properties&quot;">​</a></h2><h3 id="artifactname" tabindex="-1"><code>artifactName</code> <a class="header-anchor" href="#artifactname" aria-label="Permalink to &quot;`artifactName`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The display name of the parent POM for the generated project. This could be the name of your software product, e.g. <code>Product</code>, or be generic, e.g. <code>License</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="customclasspathscope" tabindex="-1"><code>customClasspathScope</code> <a class="header-anchor" href="#customclasspathscope" aria-label="Permalink to &quot;`customClasspathScope`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>Declares the scope of the class path for the custom classes referenced by the properties with the name pattern <code>*Class</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>Enter <code>compile</code> to declare that custom classes are available on the class path at compile time. The advantage is that the classes can be safely included in the byte code obfuscation process. The disadvantage is that the classes need to be known at compile time so that manual editing of the dependencies in the generated POM files for the Key Generator or Key Manager module may be necessary.</p><p>Enter <code>runtime</code> to declare that custom classes are available on the class path at runtime only. The advantage is that the classes don&#39;t need to be known at compile time so that manual editing of the generated POM files should not be necessary. The disadvantage is that the classes need to be generally excluded from the byte code obfuscation process, e.g. for the Key Manager module. This is considered to be a security leak and therefore should be generally avoided. However, this is not true for <a href="https://www.guardsquare.com/en/products/proguard" target="_blank" rel="noreferrer">ProGuard</a>: TrueLicense generates code for dynamic class loading which is correctly recognized and obfuscated by ProGuard so that it&#39;s safe to use this option with ProGuard.</p></dd><dt><strong>Default Value</strong></dt><dd><p><code>compile</code></p></dd></dl><h3 id="disablewizard" tabindex="-1"><code>disableWizard</code> <a class="header-anchor" href="#disablewizard" aria-label="Permalink to &quot;`disableWizard`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>Whether the Swing wizard dialog in the Key Manager module should be disabled or not. Enter <code>true</code> to remove the dependency on the TrueLicense Swing module and reduce the code size.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#boolean" target="_blank" rel="noreferrer">boolean</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>false</code></p></dd></dl><h3 id="editions" tabindex="-1"><code>editions</code> <a class="header-anchor" href="#editions" aria-label="Permalink to &quot;`editions`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>A space separated list of edition names, ordered from supersets to subsets, e.g. <code>enterprise standard</code>. Each name must be a valid Java identifier name and should be camel-cased with a lower-case initial character. The names <code>edition</code> and <code>ftp</code> are reserved for internal use.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>A space separated list of valid identifiers in the Java language.</p></dd><dt><strong>Default Value</strong></dt><dd><p><code>standard</code></p></dd></dl><h3 id="freetrialperiod" tabindex="-1"><code>freeTrialPeriod</code> <a class="header-anchor" href="#freetrialperiod" aria-label="Permalink to &quot;`freeTrialPeriod`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The number of days for an auto-generated Free Trial Period (FTP). Needs to be a non-negative integer, e.g. <code>30</code>. Specify <code>0</code> to disable the auto-generation of FTP license keys.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#nonNegativeInteger" target="_blank" rel="noreferrer">nonNegativeInteger</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>0</code></p></dd></dl><h3 id="ftpkeystorefile" tabindex="-1"><code>ftpKeyStoreFile</code> <a class="header-anchor" href="#ftpkeystorefile" aria-label="Permalink to &quot;`ftpKeyStoreFile`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The path of the FTP keystore file in the Key Manager module relative to the base path <code>keymgr/src/main/resources/</code>. This property gets ignored if the property <a href="#freetrialperiod">freeTrialPeriod</a> is set to <code>0</code>. Otherwise, if this property is set to <code>-</code>, then it gets overridden by the property <a href="#publickeystorefile">publicKeyStoreFile</a>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="ftpsecretmarkerclass" tabindex="-1"><code>ftpSecretMarkerClass</code> <a class="header-anchor" href="#ftpsecretmarkerclass" aria-label="Permalink to &quot;`ftpSecretMarkerClass`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>A fully qualified binary class name which declares the user or system preferences node to use for storing the auto-generated FTP license key. This property gets ignored if the property <a href="#freetrialperiod">freeTrialPeriod</a> is set to <code>0</code>. Otherwise, the <strong>package name</strong> of the referenced class needs to be <strong>kept secret</strong> because removing the FTP license key from the preferences&#39; node triggers the auto-generation of another FTP license key! The named class gets dynamically loaded at run time, so it doesn&#39;t have to be on the compile-time class path of the Key Manager module.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="hideuninstallaction" tabindex="-1"><code>hideUninstallAction</code> <a class="header-anchor" href="#hideuninstallaction" aria-label="Permalink to &quot;`hideUninstallAction`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>Whether the Swing wizard dialog in the Key Manager module should hide the action for uninstalling the license key or not.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#boolean" target="_blank" rel="noreferrer">boolean</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>false</code></p></dd></dl><h3 id="keygenauthorization" tabindex="-1"><code>keyGenAuthorization</code> <a class="header-anchor" href="#keygenauthorization" aria-label="Permalink to &quot;`keyGenAuthorization`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>An expression of the type <code>global.namespace.truelicense.api.LicenseManagementAuthorization</code> for use in the Key Generator module. Enter <code>-</code> to use no license authorization.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="keygenvalidation" tabindex="-1"><code>keyGenValidation</code> <a class="header-anchor" href="#keygenvalidation" aria-label="Permalink to &quot;`keyGenValidation`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>An expression of the type <code>global.namespace.truelicense.api.LicenseValidation</code> for use in the Key Generator module. Enter <code>-</code> to use only the built-in license validation function.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="keygenvalidationcomposition" tabindex="-1"><code>keyGenValidationComposition</code> <a class="header-anchor" href="#keygenvalidationcomposition" aria-label="Permalink to &quot;`keyGenValidationComposition`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>Selects the composition strategy for license validation functions in the Key Generator module. This property gets ignored if the property <a href="#keygenvalidation">keyGenValidation</a> is set to <code>-</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>Enter <code>override</code> to apply only the custom function. Enter <code>decorate</code> to apply both the custom function and the built-in function.</p></dd><dt><strong>Default Value</strong></dt><dd><p><code>decorate</code></p></dd></dl><h3 id="keymgrauthorization" tabindex="-1"><code>keyMgrAuthorization</code> <a class="header-anchor" href="#keymgrauthorization" aria-label="Permalink to &quot;`keyMgrAuthorization`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>An expression of the type <code>global.namespace.truelicense.api.LicenseManagementAuthorization</code> for use in the Key Manager module. Enter <code>-</code> to use no license authorization.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="keymgrclock" tabindex="-1"><code>keyMgrClock</code> <a class="header-anchor" href="#keymgrclock" aria-label="Permalink to &quot;`keyMgrClock`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>An expression of the type <code>java.time.Clock</code> for use in the Key Manager module. Enter <code>-</code> to use the system clock.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="keymgrvalidation" tabindex="-1"><code>keyMgrValidation</code> <a class="header-anchor" href="#keymgrvalidation" aria-label="Permalink to &quot;`keyMgrValidation`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>An expression of the type <code>global.namespace.truelicense.api.LicenseValidation</code> for use in the Key Manager module. Enter <code>-</code> to use only the built-in license validation function.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>-</code></p></dd></dl><h3 id="keymgrvalidationcomposition" tabindex="-1"><code>keyMgrValidationComposition</code> <a class="header-anchor" href="#keymgrvalidationcomposition" aria-label="Permalink to &quot;`keyMgrValidationComposition`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>Selects the composition strategy for license validation functions in the Key Manager module. This property gets ignored if the property <a href="#keymgrvalidation">keyMgrValidation</a> is set to <code>-</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>Enter <code>override</code> to apply only the custom function. Enter <code>decorate</code> to apply both the custom function and the built-in function.</p></dd><dt><strong>Default Value</strong></dt><dd><p><code>decorate</code></p></dd></dl><h3 id="keypairalgorithm" tabindex="-1"><code>keyPairAlgorithm</code> <a class="header-anchor" href="#keypairalgorithm" aria-label="Permalink to &quot;`keyPairAlgorithm`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The algorithm to use when generating key pairs in the keystore files on the first build. This property gets ignored if the keystore files already exist. The algorithm needs to be implemented by some security provider which is installed in the JRE.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>The name of a <a href="https://docs.oracle.com/en/java/javase/14/docs/specs/security/standard-names.html#keypairgenerator-algorithms" target="_blank" rel="noreferrer"><code>KeyPairGenerator</code> algorithm</a>:</p><ul><li><code>DiffieHellman</code></li><li><code>DSA</code></li><li><code>EC</code></li><li><code>RSA</code></li><li><code>RSASSA-PSS</code></li><li><code>X25519</code> (requires Java 11 or later)</li><li><code>X448</code> (requires Java 11 or later)</li><li><code>XDH</code> (requires Java 11 or later)</li></ul></dd><dt><strong>Default Value</strong></dt><dd><p><code>DSA</code></p></dd></dl><h3 id="keypairsize" tabindex="-1"><code>keyPairSize</code> <a class="header-anchor" href="#keypairsize" aria-label="Permalink to &quot;`keyPairSize`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The key size in bits when generating key pairs in the keystore files at the first build. This property gets ignored if the keystore files already exist. Otherwise, if it&#39;s <code>0</code>, then the property gets overridden by the keytool. Otherwise, the bit size needs to correspond to the property <a href="#keypairalgorithm">keyPairAlgorithm</a> and be implemented by some security provider which is installed in the JRE.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#nonNegativeInteger" target="_blank" rel="noreferrer">nonNegativeInteger</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>0</code></p></dd></dl><h3 id="keystoretype" tabindex="-1"><code>keyStoreType</code> <a class="header-anchor" href="#keystoretype" aria-label="Permalink to &quot;`keyStoreType`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The default keystore type. The type needs to be implemented by some security provider which is installed in the JRE.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>The name of a <a href="https://docs.oracle.com/en/java/javase/14/docs/specs/security/standard-names.html#keystore-types" target="_blank" rel="noreferrer"><code>KeyStore</code> type</a>:</p><ul><li><code>DKS</code></li><li><code>JCEKS</code></li><li><code>JKS</code></li><li><code>PKCS11</code></li><li><code>PKCS12</code></li></ul></dd><dt><strong>Default Value</strong></dt><dd><p>If the property <a href="#licensekeyformat">licenseKeyFormat</a> is set to <code>V1</code>, then this property gets set to <code>JKS</code>, or else if the property <a href="#licensekeyformat">licenseKeyFormat</a> starts with <code>V2/</code>, then it gets set to <code>JCEKS</code>, or else to <code>PKCS12</code>.</p></dd></dl><h3 id="licensekeyformat" tabindex="-1"><code>licenseKeyFormat</code> <a class="header-anchor" href="#licensekeyformat" aria-label="Permalink to &quot;`licenseKeyFormat`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The format of the license keys. Enter <code>V4</code> to benefit from the latest cryptographic standards. It was introduced in TrueLicense 4 and depends on the Jackson JSON Processor. Enter <code>V2/JSON</code> only if you need to retain compatibility with this license key format. It was introduced in TrueLicense 2 and depends on the Jackson JSON Processor. Enter <code>V2/XML</code> only if you need to retain compatibility with this license key format. It was introduced in TrueLicense 2 and depends on the JAXB API and runtime. Enter <code>V1</code> only if you need to retain compatibility with this license key format. It was introduced in TrueLicense 1.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>One of:</p><ul><li><code>V1</code></li><li><code>V2/XML</code></li><li><code>V2/JSON</code></li><li><code>V4</code></li></ul></dd><dt><strong>Default Value</strong></dt><dd><p><code>V4</code></p></dd></dl><h3 id="package" tabindex="-1"><code>package</code> <a class="header-anchor" href="#package" aria-label="Permalink to &quot;`package`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The base package name of the generated project. It&#39;s best practice evaluating the expression <code>${groupId}</code> or <code>${groupId}.${artifactId}</code> if this results in a valid package name.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p>The value of the property <a href="#groupid">groupId</a>.</p></dd></dl><h3 id="pbealgorithm" tabindex="-1"><code>pbeAlgorithm</code> <a class="header-anchor" href="#pbealgorithm" aria-label="Permalink to &quot;`pbeAlgorithm`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The algorithm for the password based encryption. The algorithm needs to be implemented by some security provider which is installed in the JRE.</p></dd><dt><strong>Type</strong></dt><dd><p>The name of a <a href="https://docs.oracle.com/en/java/javase/14/docs/specs/security/standard-names.html#cipher-algorithm-names" target="_blank" rel="noreferrer"><code>Cipher</code> algorithm</a>:</p><ul><li><code>PBEWithMD5AndDES</code></li><li><code>PBEWithMD5AndTripleDES</code></li><li><code>PBEWithSHA1AndDESede</code></li><li><code>PBEWithSHA1AndRC2_40</code></li><li><code>PBEWithSHA1AndRC2_128</code></li><li><code>PBEWithSHA1AndRC4_40</code></li><li><code>PBEWithSHA1AndRC4_128</code></li><li><code>PBEWithHmacSHA1AndAES_128</code></li><li><code>PBEWithHmacSHA224AndAES_128</code></li><li><code>PBEWithHmacSHA256AndAES_128</code></li><li><code>PBEWithHmacSHA384AndAES_128</code></li><li><code>PBEWithHmacSHA512AndAES_128</code></li><li><code>PBEWithHmacSHA1AndAES_256</code></li><li><code>PBEWithHmacSHA224AndAES_256</code></li><li><code>PBEWithHmacSHA256AndAES_256</code></li><li><code>PBEWithHmacSHA384AndAES_256</code></li><li><code>PBEWithHmacSHA512AndAES_256</code></li></ul></dd><dt><strong>Default Value</strong></dt><dd><p>If the property <a href="#licensekeyformat">licenseKeyFormat</a> is set to <code>V1</code>, then this property gets set to <code>PBEWithMD5AndDES</code>, or else if the property <a href="#licensekeyformat">licenseKeyFormat</a> starts with <code>V2/</code>, then it gets set to <code>PBEWithSHA1AndDESede</code>, or else to <code>PBEWithHmacSHA256AndAES_128</code>.</p></dd></dl><h3 id="preferencestype" tabindex="-1"><code>preferencesType</code> <a class="header-anchor" href="#preferencestype" aria-label="Permalink to &quot;`preferencesType`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The type of the preferences nodes where to install license keys. Note that <code>system</code> generally requires the JVM to be run with administrator privileges or otherwise a <code>java.util.prefs.BackingStoreException</code> may get thrown by the generated integration tests.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>One of:</p><ul><li><code>system</code></li><li><code>user</code></li></ul></dd><dt><strong>Default Value</strong></dt><dd><p><code>user</code></p></dd></dl><h3 id="privatekeystorefile" tabindex="-1"><code>privateKeyStoreFile</code> <a class="header-anchor" href="#privatekeystorefile" aria-label="Permalink to &quot;`privateKeyStoreFile`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The path of the private keystore file in the Key Generator module relative to the base path <code>keygen/src/main/resources/</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>private.ks</code></p></dd></dl><h3 id="publickeystorefile" tabindex="-1"><code>publicKeyStoreFile</code> <a class="header-anchor" href="#publickeystorefile" aria-label="Permalink to &quot;`publicKeyStoreFile`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The path of the public keystore file in the Key Manager module relative to the base path <code>keymgr/src/main/resources/</code>.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>public.ks</code></p></dd></dl><h3 id="signaturealgorithm" tabindex="-1"><code>signatureAlgorithm</code> <a class="header-anchor" href="#signaturealgorithm" aria-label="Permalink to &quot;`signatureAlgorithm`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The algorithm to use when signing a generated key pair in a keystore file at the first build. This property gets ignored if the keystore file already exists. The signature algorithm needs to correspond to the property <a href="#keypairalgorithm">keyPairAlgorithm</a> and be implemented by some security provider which is installed in the JRE.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p>The name of a <a href="https://docs.oracle.com/en/java/javase/14/docs/specs/security/standard-names.html#signature-algorithms" target="_blank" rel="noreferrer"><code>Signature</code> algorithm</a>:</p><ul><li><code>NONEwithDSA</code></li><li><code>SHA1withDSA</code></li><li><code>SHA224withDSA</code></li><li><code>SHA256withDSA</code></li><li><code>SHA384withDSA</code></li><li><code>SHA512withDSA</code></li><li><code>SHA3-224withDSA</code></li><li><code>SHA3-256withDSA</code></li><li><code>SHA3-384withDSA</code></li><li><code>SHA3-512withDSA</code></li><li><code>NONEwithDSAinP1363Format</code></li><li><code>SHA1withDSAinP1363Format</code></li><li><code>SHA224withDSAinP1363Format</code></li><li><code>SHA256withDSAinP1363Format</code></li><li><code>NONEwithECDSA</code></li><li><code>SHA1withECDSA</code></li><li><code>SHA224withECDSA</code></li><li><code>SHA256withECDSA</code></li><li><code>SHA384withECDSA</code></li><li><code>SHA512withECDSA</code></li><li><code>SHA3-224withECDSA</code></li><li><code>SHA3-256withECDSA</code></li><li><code>SHA3-384withECDSA</code></li><li><code>SHA3-512withECDSA</code></li><li><code>NONEwithECDSAinP1363Format</code></li><li><code>SHA1withECDSAinP1363Format</code></li><li><code>SHA224withECDSAinP1363Format</code></li><li><code>SHA256withECDSAinP1363Format</code></li><li><code>SHA384withECDSAinP1363Format</code></li><li><code>SHA512withECDSAinP1363Format</code></li><li><code>NONEwithRSA</code></li><li><code>MD2withRSA</code></li><li><code>MD5withRSA</code></li><li><code>SHA1withRSA</code></li><li><code>SHA224withRSA</code></li><li><code>SHA256withRSA</code></li><li><code>SHA384withRSA</code></li><li><code>SHA512withRSA</code></li><li><code>SHA512/224withRSA</code></li><li><code>SHA512/256withRSA</code></li><li><code>SHA3-224withRSA</code></li><li><code>SHA3-256withRSA</code></li><li><code>SHA3-384withRSA</code></li><li><code>SHA3-512withRSA</code></li><li><code>RSASSA-PSS</code></li></ul></dd><dt><strong>Default Value</strong></dt><dd><p>The property value gets determined by the keytool.</p></dd></dl><h3 id="truelicenseversion" tabindex="-1"><code>trueLicenseVersion</code> <a class="header-anchor" href="#truelicenseversion" aria-label="Permalink to &quot;`trueLicenseVersion`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>The TrueLicense version to use.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#token" target="_blank" rel="noreferrer">token</a></p></dd><dt><strong>Default Value</strong></dt><dd><p>The version of the latest release as of the release date of the TrueLicense Maven Archetype.</p></dd></dl><h3 id="verbosecli" tabindex="-1"><code>verboseCli</code> <a class="header-anchor" href="#verbosecli" aria-label="Permalink to &quot;`verboseCli`&quot;">​</a></h3><dl><dt><strong>Description</strong></dt><dd><p>Whether the command line interface (CLI) should write debugging information to the standard error stream by default or not.</p><p> </p></dd><dt><strong>Type</strong></dt><dd><p><a href="https://www.w3.org/TR/xmlschema-2/#boolean" target="_blank" rel="noreferrer">boolean</a></p></dd><dt><strong>Default Value</strong></dt><dd><p><code>false</code></p></dd></dl>',73)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
